const fs = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
if (!inputPath) throw new Error('INPUT_PATH is required');
if (!fs.existsSync(inputPath)) throw new Error(`Input file not found: ${inputPath}`);
const xmlContent = fs.readFileSync(inputPath, 'utf8');
globalThis.xmlContent = xmlContent;
globalThis.outputPath = process.env.OUTPUT_PATH || '/tmp/output.toml';

const jsp = (await import('jsparsers')).default || (await import('jsparsers'));
const xmlParser = jsp.xml();
const jsonResult = xmlParser.parse(globalThis.xmlContent);
const tomlParser = jsp.toml();
const tomlString = tomlParser.serialize(jsonResult);
globalThis.tomlString = tomlString;

const fs = await import('node:fs');
fs.writeFileSync(globalThis.outputPath, globalThis.tomlString, 'utf8');
console.log(JSON.stringify({ output_path: globalThis.outputPath, success: true }));
